inverterInput.excerpt:
vvp_fun_buf_not_::vvp_fun_buf_not_(unsigned wid)
: input_(wid, BIT4_Z)
{
      net_ = 0;
}

vvp_fun_buf_not_::~vvp_fun_buf_not_()
{
}

void vvp_fun_buf_not_::recv_vec4(vvp_net_ptr_t ptr, const vvp_vector4_t&bit,
                                 vvp_context_t)
{
      if (ptr.port() != 0) return;

      if (input_ .eeq( bit )) return;

      input_ = bit;
      if (net_ == 0) {
	    net_ = ptr.ptr();
	    schedule_functor(this);
      }
}

void vvp_fun_buf_not_::recv_vec4_pv(vvp_net_ptr_t ptr, const vvp_vector4_t&bit,
                                    unsigned base, unsigned vwid, vvp_context_t)
{
      if (ptr.port() != 0) return;

      assert(base + bit.size() <= vwid);

	// Set the input part. If nothing changes, then break.
      bool flag = input_.set_vec(base, bit);
      if (flag == false) return;

      if (net_ == 0) {
	    net_ = ptr.ptr();
	    schedule_functor(this);
      }
}

void vvp_fun_buf_not_::recv_real(vvp_net_ptr_t ptr, double real,
                                 vvp_context_t ctx)
{
      if (ptr.port() != 0) return;

      recv_vec4(ptr, double_to_vector4_LSB(real), ctx);
}

inverterExecution.excerpt:
void vvp_fun_not::run_run()
{
      vvp_net_t*ptr = net_;
      net_ = 0;

      vvp_vector4_t result (input_, true /* invert */);
      ptr->send_vec4(result, 0);
}

partSelect.excerpt:
vvp_fun_part_sa::vvp_fun_part_sa(unsigned base, unsigned wid)
: vvp_fun_part(base, wid)
{
      robotron_vvp_primitive_register(static_cast<vvp_gen_event_s*>(this),this,2,robotron_payload,robotron_toggle);
      net_ = 0;
}

vvp_fun_part_sa::~vvp_fun_part_sa()
{
      robotron_vvp_primitive_unregister(static_cast<vvp_gen_event_s*>(this));
}

void vvp_fun_part_sa::recv_vec4(vvp_net_ptr_t port, const vvp_vector4_t&bit,
                                vvp_context_t)
{
      assert(port.port() == 0);

      vvp_vector4_t tmp (bit, base_, wid_);
      if (val_ .eeq( tmp ))
	    return;

      val_ = tmp;

      if (net_ == 0) {
	    net_ = port.ptr();
	    schedule_functor(this);
      }
}

/*
 * Handle the case that the part select node is actually fed by a part
 * select assignment. It's not exactly clear what might make this
 * happen, but is does seem to happen and this should have well
 * defined behavior.
 */
void vvp_fun_part_sa::recv_vec4_pv(vvp_net_ptr_t port, const vvp_vector4_t&bit,
				   unsigned base, unsigned vwid, vvp_context_t)
{
      vvp_vector4_t tmp (vwid, BIT4_Z);
      tmp.set_vec(base_, val_);
      tmp.set_vec(base, bit);
      recv_vec4(port, tmp, 0);
}

void vvp_fun_part_sa::run_run()
{
      vvp_net_t*ptr = net_;
      net_ = 0;
      ptr->send_vec4(val_, 0);
}
